import { Slot } from '@radix-ui/react-slot';
import type * as React from 'react';

function Card({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="card"
      // Canonical Card per DESIGN_GUIDELINES §2: the only elevated container.
      // Border is baked in here so call sites stop appending `border` /
      // `border-border/80` / `shadow-sm` ad-hoc. If you need to tune the
      // border treatment, tune this string — not the call site.
      className={`bg-card text-card-foreground flex flex-col gap-6 rounded-2xl border py-6 ${className || ''}`}
      {...props}
    />
  );
}

function CardHeader({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="card-header"
      className={`grid auto-rows-min grid-rows-[auto_auto] items-start gap-1.5 px-6 has-data-[slot=card-action]:grid-cols-[1fr_auto] ${className || ''}`}
      {...props}
    />
  );
}

/**
 * Card title. Renders a `div` by default — accessible heading semantics are
 * the caller's responsibility because Cards appear at many depths in the
 * heading outline (a single page may have multiple top-level Cards under one
 * `<h1>`, or a Card may be a sub-section under an `<h2>`).
 *
 * When a CardTitle IS the page-level heading (e.g. an auth page where the
 * Card is the entire content), pass `asChild` and render an explicit `<h1>`
 * (or whichever heading level fits the outline):
 *
 *     <CardTitle asChild>
 *       <h1>Reset your password</h1>
 *     </CardTitle>
 *
 * The Slot merges Card's typography classes onto the heading element, so the
 * visual is unchanged. See DESIGN_GUIDELINES §2.
 */
function CardTitle({
  className,
  asChild = false,
  ...props
}: React.ComponentProps<'div'> & { asChild?: boolean }) {
  const Comp = asChild ? Slot : 'div';
  return (
    <Comp
      data-slot="card-title"
      className={`leading-none font-semibold ${className || ''}`}
      {...props}
    />
  );
}

function CardDescription({ className, ...props }: React.ComponentProps<'div'>) {
  return (
    <div
      data-slot="card-description"
      className={`mt-1 first:mt-0 text-muted-foreground text-sm ${className || ''}`}
      {...props}
    />
  );
}

function CardContent({ className, ...props }: React.ComponentProps<'div'>) {
  return <div data-slot="card-content" className={`px-6 ${className || ''}`} {...props} />;
}

export { Card, CardHeader, CardTitle, CardDescription, CardContent };
