/* Fix better-auth-ui social button icon sizing.
 * Scoped with :not(.lucide) so our own lucide-react icons keep their Tailwind
 * size classes — otherwise the `button svg[viewBox="0 0 24 24"]` rule (higher
 * specificity than the nav/aside override below) forces e.g. the sidebar Search
 * icon to 20px while sibling nav links stay at 16px. */
button svg[viewBox="0 0 24 24"]:not(.lucide),
button svg[viewBox="0 0 186.69 190.5"]:not(.lucide),
button svg:not(.lucide) {
  width: 1.25rem !important;
  height: 1.25rem !important;
  max-width: 1.25rem !important;
  max-height: 1.25rem !important;
  flex-shrink: 0 !important;
}

/* Exclude icons in navigation */
nav svg,
aside svg {
  width: 1rem !important;
  height: 1rem !important;
  max-width: 1rem !important;
  max-height: 1rem !important;
}

/* Fix better-auth-ui avatar sizing globally */
.size-8 {
  width: 2rem !important;
  height: 2rem !important;
  max-width: 2rem !important;
  max-height: 2rem !important;
}

.size-8 img {
  width: 100% !important;
  height: 100% !important;
  max-width: 100% !important;
  max-height: 100% !important;
  object-fit: cover !important;
}

/* Keyboard hint for the attention list — only on wide screens, only when the
 * list is actually rendered. */
.attention-shortcut-hint {
  display: none;
}

@media (min-width: 64rem) {
  [data-attention-list] .attention-shortcut-hint {
    display: flex;
  }
}

/* Agent chat — ChatGPT-style thinking shimmer (see thinking-indicator.tsx). */
@keyframes thinking-shimmer {
  0% {
    background-position: 200% center;
  }
  100% {
    background-position: -200% center;
  }
}

.aui-thinking-shimmer {
  background: linear-gradient(
    90deg,
    var(--muted-foreground) 0%,
    var(--muted-foreground) 35%,
    var(--foreground) 50%,
    var(--muted-foreground) 65%,
    var(--muted-foreground) 100%
  );
  background-size: 200% 100%;
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  animation: thinking-shimmer 2.2s ease-in-out infinite;
}

